package net.minecraft.world.entity;import net.minecraft.world.level.Level;public class LivingEntity extends Entity{public float health=48;public java.util.Map<Object,net.minecraft.world.entity.ai.attributes.AttributeInstance> attrs=new java.util.HashMap<>();public net.minecraft.world.entity.ai.attributes.AttributeInstance getAttribute(Object key){return attrs.computeIfAbsent(key,k->new net.minecraft.world.entity.ai.attributes.AttributeInstance());}public float getHealth(){return health;}public void setHealth(float f){health=f;}public LivingEntity(Level l){super(l);}}